def write_surah(n: int, ayahs: dict) -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    data = {"surah": n, "ayahs": {str(k): v for k, v in sorted(ayahs.items())}}
    path = OUT / f"surah_{n}.json"
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {path.name}: {len(ayahs)} ayahs")


if __name__ == "__main__":
    for surah_num, ayahs in TRANSLATIONS.items():
        write_surah(surah_num, ayahs)
